<script>
(function($){
 var modal=$('#performanceOrderModal'),title=$('#performanceOrderTitle'),body=$('#performanceOrderBody'),url=@json(route('fashion.performance-report.orders')),current={date:'',storeId:'',storeName:'',timezone:'+00:00'};
 function esc(v){return $('<div>').text(v==null?'':String(v)).html()}
 function money(v,c){return esc(c||'USD')+' '+Number(v||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})}
 function pageButtons(meta){var html='<div class="order-detail-pagination"><span>显示 '+meta.from+'-'+meta.to+' 条，共 '+meta.total+' 条　第 '+meta.current_page+' / '+meta.last_page+' 页</span><div class="order-detail-pages">';html+='<button data-order-page="'+(meta.current_page-1)+'" '+(meta.current_page<=1?'disabled':'')+'><i class="fa fa-angle-left"></i></button>';var start=Math.max(1,meta.current_page-2),end=Math.min(meta.last_page,start+4);start=Math.max(1,end-4);for(var i=start;i<=end;i++)html+='<button data-order-page="'+i+'" class="'+(i===meta.current_page?'active':'')+'">'+i+'</button>';html+='<button data-order-page="'+(meta.current_page+1)+'" '+(meta.current_page>=meta.last_page?'disabled':'')+'><i class="fa fa-angle-right"></i></button></div></div>';return html}
 function load(page){body.html('<div class="order-loading"><i class="fa fa-spinner fa-spin fa-2x"></i><br><br>正在加载订单...</div>');$.get(url,{date:current.date,store_id:current.storeId,timezone:current.timezone,page:page||1}).done(function(data){var html='<div class="order-detail-summary"><span>订单：<b>'+data.count+' 单</b></span><span>营业额：<b>$'+Number(data.amount||0).toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2})+'</b></span><span>时区：<b>UTC'+esc(current.timezone)+'</b></span></div>';if(!data.orders.length){body.html(html+'<div class="order-empty">暂无订单</div>');return}html+='<div class="order-detail-wrap"><table class="table table-bordered order-detail-table"><thead><tr><th>订单号</th><th>下单时间</th><th>付款时间</th><th>客户</th><th>商品内容</th><th>支付方式</th><th>状态</th><th>订单金额</th></tr></thead><tbody>';data.orders.forEach(function(order){var products=(order.items||[]).map(function(item){return '<div class="order-product"><b>'+esc(item.product_name)+'</b><br><small>SKU：'+esc(item.sku)+'　数量：'+esc(item.quantity)+'　小计：'+money(item.total,order.currency)+'</small></div>'}).join('')||'—';html+='<tr><td><b>'+esc(order.order_number)+'</b></td><td>'+esc(order.order_created_at||'—')+'</td><td>'+esc(order.paid_at||'—')+'</td><td>'+esc(order.customer_name)+'<br><small>'+esc(order.customer_email)+'</small></td><td class="order-products">'+products+'</td><td>'+esc(order.payment_method)+'</td><td>'+esc(order.status)+'</td><td class="text-right"><b>'+money(order.total_amount,order.currency)+'</b></td></tr>'});html+='</tbody></table></div>'+pageButtons(data.pagination);body.html(html)}).fail(function(xhr){body.html('<div class="order-empty text-danger"><i class="fa fa-exclamation-circle"></i> '+esc((xhr.responseJSON&&xhr.responseJSON.message)||'订单加载失败，请稍后重试')+'</div>')})}
 document.addEventListener('click',function(e){var button=e.target.closest('.order-count-link');if(button){current={date:button.dataset.orderDate,storeId:button.dataset.storeId,storeName:button.dataset.storeName,timezone:button.dataset.timezone};title.text(current.storeName+' · '+current.date+' 订单明细');modal.modal('show');load(1);return}var pager=e.target.closest('[data-order-page]');if(pager&&!pager.disabled)load(Number(pager.dataset.orderPage))});
})(jQuery);
</script>
@endpush
